# 2. Refactor testMt5ConnectionInner's Python script
old_test = """pythonScript: `import json,time,os,MetaTrader5 as mt5\\nt=time.time()\\ntp=os.environ.get(\\"SYNTHETIC_MT5_TERMINAL_PATH\\",\\"\\")\\nsv=os.environ.get(\\"SYNTHETIC_MT5_SERVER\\",\\"\\")\\nlg=int(os.environ.get(\\"SYNTHETIC_MT5_LOGIN\\",\\"0\\"))\\npw=os.environ.get(\\"SYNTHETIC_MT5_PASSWORD\\",\\"\\")\\nr={\\"success\\":False,\\"error\\":None,\\"server\\":sv,\\"terminal_path\\":tp or None}\\ntry:\\n x=mt5.initialize(path=tp,portable=True)if tp else mt5.initialize(portable=True)\\n if not x:\\n  r[\\"error\\"]=\\"init: %s\\"%str(mt5.last_error())\\n else:\\n  y=mt5.login(lg,password=pw,server=sv)\\n  if not y:\\n   r[\\"error\\"]=\\"login: %s\\"%str(mt5.last_error())\\n  else:\\n   a=mt5.account_info()\\n   r.update({\\"success\\":True,\\"account_name\\":a.name if a else \\"unknown\\",\\"account_balance\\":a.balance if a else 0.0})\\nexcept Exception as e:\\n r[\\"error\\"]=\\"E: %s\\"%e\\nfinally:\\n mt5.shutdown()\\nr[\\"duration_ms\\"]=int((time.time()-t)*1000)\\nprint(json.dumps(r))`,"""

