# 3. Refactor closePosition
old_close = """    const pythonScript = `\nimport json\nimport MetaTrader5 as mt5\n\ntry:\n    terminal_path = ${JSON.stringify(configuredTerminal || null)}\n    if terminal_path:\n        initialized = mt5.initialize(path=terminal_path, portable=True)\n    else:\n        initialized = mt5.initialize(portable=True)\n\n    if not initialized:\n        print(json.dumps({"closed": False, "message": f"MT5 init failed: {mt5.last_error()}"}))\n        raise SystemExit(0)\n\n    if not mt5.login(${configuredLogin}, password=${JSON.stringify(configuredPassword)}, server=${JSON.stringify(configuredServer)}):\n        print(json.dumps({"closed": False, "message": f"MT5 login failed: {mt5.last_error()}"}))\n        raise SystemExit(0)\n\n    positions = mt5.positions_get(ticket=${mt5Ticket})\n    if not positions:\n        print(json.dumps({"closed": False, "message": "Position not found."}))\n        raise SystemExit(0)\n\n    pos = positions[0]\n    close_type = mt5.ORDER_TYPE_SELL if pos.type == 0 else mt5.ORDER_TYPE_BUY\n\n    request = {\n        "action": mt5.TRADE_ACTION_DEAL,\n        "position": pos.ticket,\n        "symbol": pos.symbol,\n        "volume": pos.volume,\n        "type": close_type,\n        "price": mt5.symbol_info_tick(pos.symbol).bid if close_type == mt5.ORDER_TYPE_SELL else mt5.symbol_info_tick(pos.symbol).ask,\n        "deviation": 20,\n        "magic": 123456,\n        "comment": "synthetic-trader-close",\n        "type_time": mt5.ORDER_TIME_GTC,\n        "type_filling": mt5.ORDER_FILLING_FOK,\n    }\n\n    result = mt5.order_send(request)\n    if result is None:\n        print(json.dumps({"closed": False, "message": "Close order returned None."}))\n    elif result.retcode == mt5.TRADE_RETCODE_DONE:\n        print(json.dumps({"closed": True, "message": f"Position closed. Ticket: {pos.ticket}"}))\n    else:\n        print(json.dumps({"closed": False, "message": f"Close failed. Retcode: {result.retcode}"}))\nexcept Exception as e:\n    print(json.dumps({"closed": False, "message": f"Close position error: {e}"}))\nfinally:\n    mt5.shutdown()"""

new_close = """    const pythonScript = `\nimport json\nimport MetaTrader5 as mt5\n${MT5_CTX}\n\ntry:\n    with _mt5(tp=${JSON.stringify(configuredTerminal || null)},lg=${configuredLogin},pw=${JSON.stringify(configuredPassword)},sv=${JSON.stringify(configuredServer)}):\n        positions = mt5.positions_get(ticket=${mt5Ticket})\n        if not positions:\n            print(json.dumps({"closed": False, "message": "Position not found."}))\n            raise SystemExit(0)\n\n        pos = positions[0]\n        close_type = mt5.ORDER_TYPE_SELL if pos.type == 0 else mt5.ORDER_TYPE_BUY\n\n        request = {\n            "action": mt5.TRADE_ACTION_DEAL,\n            "position": pos.ticket,\n            "symbol": pos.symbol,\n            "volume": pos.volume,\n            "type": close_type,\n            "price": mt5.symbol_info_tick(pos.symbol).bid if close_type == mt5.ORDER_TYPE_SELL else mt5.symbol_info_tick(pos.symbol).ask,\n            "deviation": 20,\n            "magic": 123456,\n            "comment": "synthetic-trader-close",\n            "type_time": mt5.ORDER_TIME_GTC,\n            "type_filling": mt5.ORDER_FILLING_FOK,\n        }\n\n        result = mt5.order_send(request)\n        if result is None:\n            print(json.dumps({"closed": False, "message": "Close order returned None."}))\n        elif result.retcode == mt5.TRADE_RETCODE_DONE:\n            print(json.dumps({"closed": True, "message": f"Position closed. Ticket: {pos.ticket}"}))\n        else:\n            print(json.dumps({"closed": False, "message": f"Close failed. Retcode: {result.retcode}"}))\nexcept RuntimeError as e:\n    print(json.dumps({"closed": False, "message": f"MT5 connection error: {e}"}))\nexcept Exception as e:\n    print(json.dumps({"closed": False, "message": f"Close position error: {e}"}))"""

if old_close in content:
    content = content.replace(old_close, new_close, 1)
    print("OK: closePosition refactored")
